num = re.compile(r'-?\d[\d,]*\.?\d*')
def nums(s): 
    out=set()
    for m in num.findall(s):
        try: out.add(round(float(m.replace(',','').rstrip('.')),4))
        except: pass
    return out
def classify(g):
    p = P[g['id']]; 
    try: pred = round(float(str(g['pred']).replace(',','')),4); gold = round(float(str(g['gold']).replace(',','')),4)
    except: return 'unparsable'
