    if not inter: inter = nums(sol.split('####')[0])
    inter.discard(gold)
    if pred in inter: return 'intermediate'
    if pred in nums(p['problem']): return 'given_number'
    if gold!=0 and any(abs(pred - gold*f) < 1e-6 for f in (10,100,0.1,0.01,-1)): return 'scale_sign'
